264	c41d6549-bb4d-4f1b-9305-27a8c46dbaa2	\N	263	265	ecpg-variables.html	html	\N	\N	34.4. Using Host Variables#	\N	\N	\N	\N	34.4. Using Host Variables#	\N	\N	\N	\N	18	en	{"title": "34.4. Using Host Variables#", "filename": "ecpg-variables.html", "chunk_count": 12, "chunk_index": 4}	Page: 34.4. Using Host Variables#\nSource: ecpg-variables.html\n\nEXEC SQL END DECLARE SECTION;\n\n    EXEC SQL CONNECT TO testdb;\n    EXEC SQL SELECT pg_catalog.set_config('search_path', '', false); EXEC SQL COMMIT;\n\n    in = PGTYPESinterval_new();\n    EXEC SQL SELECT '1 min'::interval INTO :in;\n    printf("interval = %s\\n", PGTYPESinterval_to_asc(in));\n    PGTYPESinterval_free(in);\n\n    EXEC SQL COMMIT;\n    EXEC SQL DISCONNECT ALL;\n    return 0;\n}\n34.4.4.2.3. numeric, decimal\n#\nThe handling of the\nnumeric\nand\ndecimal\ntypes is similar to the\ninterval\ntype: It requires defining a pointer, allocating some memory space on the heap, and accessing the variable using the pgtypes library functions. For more details about the pgtypes library functions, see\nSection 34.6\n.\nNo functions are provided specifically for the\ndecimal\ntype. An application has to convert it to a\nnumeric\nvariable using a pgtypes library function to do further processing.\nHere is an example program handling\nnumeric\nand\ndecimal\ntype variables.\n#include <stdio.h>\n#include <stdlib.h>\n#include <pgtypes_numeric.h>\n\nEXEC SQL WHENEVER SQLERROR STOP;\n\nint\nmain(void)\n{\nEXEC SQL BEGIN DECLARE SECTION;\n    numeric *num;\n    numeric *num2;\n    decimal *dec;\nEXEC SQL END DECLARE SECTION;\n\n    EXEC SQL CONNECT TO testdb;\n    EXEC SQL SELECT pg_catalog.set_config('search_path', '', false); EXEC SQL COMMIT;\n\n    num = PGTYPESnumeric_new();\n    dec = PGTYPESdecimal_new();\n\n    EXEC SQL SELECT 12.345::numeric(4,2), 23.456::decimal(4,2) INTO :num, :dec;\n\n    printf("numeric = %s\\n", PGTYPESnumeric_to_asc(num, 0));\n    printf("numeric = %s\\n", PGTYPESnumeric_to_asc(num, 1));\n    printf("numeric = %s\\n", PGTYPESnumeric_to_asc(num, 2));\n\n    /* Convert decimal to numeric to show a decimal value. */\n    num2 = PGTYPESnumeric_new();\n    PGTYPESnumeric_from_decimal(dec, num2);\n\n    printf("decimal = %s\\n", PGTYPESnumeric_to_asc(num2, 0));\n    printf("decimal = %s\\n", PGTYPESnumeric_to_asc(num2, 1));\n    printf("decimal = %s\\n", PGTYPESnumeric_to_asc(num2, 2));\n\n    PGTYPESnumeric_free(num2);\n    PGTYPESdecimal_free(dec);\n    PGTYPESnumeric_free(num);\n\n    EXEC SQL COMMIT;\n    EXEC SQL DISCONNECT ALL;\n    return 0;\n}\n34.4.4.2.4. bytea\n#\nThe handling of the\nbytea\ntype is similar to that of\nVARCHAR\n. The definition on an array of type\nbytea\nis converted into a named struct for every variable. A declaration like:\nbytea var[180];\nis converted into:\nstruct bytea_var { int len; char arr[180]; } var;\nThe member\narr	21856dcac93896fe54fc67c5ffdf8964458da32105a1a44e98adae04d46ffbce	\N	4	12	bge-base-en-v1.5	[1.0191776,1.384838,-2.8383887,-1.7290757,0.95888877,0.07403121,0.76467466,-0.60047054,-0.9794295,-1.2249076,-0.28352264,0.057941847,0.7902473,0.08008869,0.39566135,-0.6336666,-0.38278514,-0.549832,-0.3521185,0.41535378,1.1137086,-0.41396186,-0.3575574,-0.62425226,1.5942668,1.0165962,-0.3364906,-0.0678962,-1.17669,0.78926945,0.12659478,-0.0051173526,0.9529264,-0.1593003,-0.6870639,-0.48252273,0.5436585,0.33413646,0.18764491,0.18606105,0.41229308,0.45663932,0.830191,0.34971893,-0.0063856132,-0.18073265,1.1830181,0.70216507,1.3299258,-0.9881776,-0.032564197,-0.303318,0.35479152,-0.35771772,1.2532291,0.3786767,0.14929342,0.4299396,0.94103086,-0.1459603,1.5600772,0.4548578,-1.0568196,0.49410263,0.95771897,-0.3842638,-0.6283254,0.25277707,-0.44945803,-0.763447,0.5142608,-0.047795977,-0.5434148,0.33165675,-0.23537764,-0.94073635,-0.044157587,-1.0035841,-0.6836231,0.7187294,0.10578678,-0.047502093,1.0015657,-0.34479493,-0.055768963,-0.43345007,-0.6245099,-0.13470912,-0.10879259,0.2629828,-0.39548212,0.283528,0.36254475,1.0197192,-1.