212	38ef5afe-a509-4ee0-b33a-a245dc6e432b	\N	211	213	ecpg-descriptors.html	html	\N	\N	34.7. Using Descriptor Areas#	\N	\N	\N	\N	34.7. Using Descriptor Areas#	\N	\N	\N	\N	18	en	{"title": "34.7. Using Descriptor Areas#", "filename": "ecpg-descriptors.html", "chunk_count": 10, "chunk_index": 6}	Page: 34.7. Using Descriptor Areas#\nSource: ecpg-descriptors.html\n\nsqlda2->sqlvar[1].sqllen  = sizeof(intval);\nAfter setting up the input SQLDA, open a cursor with the input SQLDA.\n/* Open a cursor with input parameters. */\n    EXEC SQL OPEN cur1 USING DESCRIPTOR sqlda2;\nFetch rows into the output SQLDA from the opened cursor. (Generally, you have to call\nFETCH\nrepeatedly in the loop, to fetch all rows in the result set.)\nwhile (1)\n    {\n        sqlda_t *cur_sqlda;\n\n        /* Assign descriptor to the cursor  */\n        EXEC SQL FETCH NEXT FROM cur1 INTO DESCRIPTOR sqlda1;\nNext, retrieve the fetched records from the SQLDA, by following the linked list of the\nsqlda_t\nstructure.\nfor (cur_sqlda = sqlda1 ;\n         cur_sqlda != NULL ;\n         cur_sqlda = cur_sqlda->desc_next)\n    {\n        ...\nRead each columns in the first record. The number of columns is stored in\nsqld\n, the actual data of the first column is stored in\nsqlvar[0]\n, both members of the\nsqlda_t\nstructure.\n/* Print every column in a row. */\n        for (i = 0; i < sqlda1->sqld; i++)\n        {\n            sqlvar_t v = sqlda1->sqlvar[i];\n            char *sqldata = v.sqldata;\n            short sqllen  = v.sqllen;\n\n            strncpy(name_buf, v.sqlname.data, v.sqlname.length);\n            name_buf[v.sqlname.length] = '\\0';\nNow, the column data is stored in the variable\nv\n. Copy every datum into host variables, looking at\nv.sqltype\nfor the type of the column.\nswitch (v.sqltype) {\n                int intval;\n                double doubleval;\n                unsigned long long int longlongval;\n\n                case ECPGt_char:\n                    memset(&var_buf, 0, sizeof(var_buf));\n                    memcpy(&var_buf, sqldata, (sizeof(var_buf) <= sqllen ? sizeof(var_buf)-1 : sqllen));\n                    break;\n\n                case ECPGt_int: /* integer */\n                    memcpy(&intval, sqldata, sqllen);\n                    snprintf(var_buf, sizeof(var_buf), "%d", intval);\n                    break;\n\n                ...\n\n                default:\n                    ...\n            }\n\n            printf("%s = %s (type: %d)\\n", name_buf, var_buf, v.sqltype);\n        }\nClose the cursor after processing all of records, and disconnect from the database.\nEXEC SQL CLOSE cur1;\n    EXEC SQL COMMIT;\n\n    EXEC SQL DISCONNECT ALL;\nThe whole program is shown in\nExample 34.1\n.\nExample 34.1. Example SQLDA Program\n#include <stdlib.h>\n#include <string.h>\n#include <stdlib.h>\n#include <stdio.h>	9290261ab744cf723da27e13497f5a73c58becc6ead2ba2bf28192b237d5a014	\N	6	10	bge-base-en-v1.5	[0.7314134,0.92215234,-2.53777,-2.1338127,1.1209925,-1.0807976,0.62568176,0.33426338,-0.78320384,-0.59520304,-1.2659676,0.17834373,1.5881532,-0.19726294,0.40610152,0.08779622,-0.86540383,-0.6897985,-0.41219994,0.33183035,-0.42582378,-0.09438654,-0.042420875,-0.3902705,0.980236,1.7067739,-0.8184864,0.4647258,-0.68295205,1.3967475,0.30687958,0.6233609,0.869001,-0.49251685,-0.99950117,-0.63771784,-0.054071926,-0.13433558,-0.026438022,0.58228236,0.53375703,-0.1688218,0.47488844,-0.7491972,-0.17935936,0.2112021,1.399114,0.4136028,0.9600039,-0.9422203,0.32648924,-0.706071,-0.14267324,-0.71305186,1.1709714,0.6718491,0.06339936,0.4196921,0.47617665,-0.34915355,1.1009675,-0.12023766,-0.60264933,1.1769487,0.51496977,-0.15943827,-0.12259848,0.6733068,-0.21285473,-0.6650982,0.12513289,-0.05820367,-0.2619553,0.028485836,-0.68752235,0.24859731,0.11101185,-0.64263314,-0.4678421,0.81886077,-0.3830289,-0.34962028,0.033187322,-0.6064094,0.12973814,0.025225908,-0.6715783,0.120326795,-0.022167495,0.42805204,0.08520345,-0.069407664,-0.031924672,0.8482958,