213	194e0225-5cf5-4668-ab5f-cfa8021e8371	\N	212	214	ecpg-descriptors.html	html	\N	\N	34.7. Using Descriptor Areas#	\N	\N	\N	\N	34.7. Using Descriptor Areas#	\N	\N	\N	\N	18	en	{"title": "34.7. Using Descriptor Areas#", "filename": "ecpg-descriptors.html", "chunk_count": 10, "chunk_index": 7}	Page: 34.7. Using Descriptor Areas#\nSource: ecpg-descriptors.html\n\n#include <unistd.h>\n\nEXEC SQL include sqlda.h;\n\nsqlda_t *sqlda1; /* descriptor for output */\nsqlda_t *sqlda2; /* descriptor for input */\n\nEXEC SQL WHENEVER NOT FOUND DO BREAK;\nEXEC SQL WHENEVER SQLERROR STOP;\n\nint\nmain(void)\n{\n    EXEC SQL BEGIN DECLARE SECTION;\n    char query[1024] = "SELECT d.oid,* FROM pg_database d, pg_stat_database s WHERE d.oid=s.datid AND ( d.datname=? OR d.oid=? )";\n\n    int intval;\n    unsigned long long int longlongval;\n    EXEC SQL END DECLARE SECTION;\n\n    EXEC SQL CONNECT TO uptimedb AS con1 USER uptime;\n    EXEC SQL SELECT pg_catalog.set_config('search_path', '', false); EXEC SQL COMMIT;\n\n    EXEC SQL PREPARE stmt1 FROM :query;\n    EXEC SQL DECLARE cur1 CURSOR FOR stmt1;\n\n    /* Create an SQLDA structure for an input parameter */\n    sqlda2 = (sqlda_t *)malloc(sizeof(sqlda_t) + sizeof(sqlvar_t));\n    memset(sqlda2, 0, sizeof(sqlda_t) + sizeof(sqlvar_t));\n    sqlda2->sqln = 2; /* a number of input variables */\n\n    sqlda2->sqlvar[0].sqltype = ECPGt_char;\n    sqlda2->sqlvar[0].sqldata = "postgres";\n    sqlda2->sqlvar[0].sqllen  = 8;\n\n    intval = 1;\n    sqlda2->sqlvar[1].sqltype = ECPGt_int;\n    sqlda2->sqlvar[1].sqldata = (char *) &intval;\n    sqlda2->sqlvar[1].sqllen  = sizeof(intval);\n\n    /* Open a cursor with input parameters. */\n    EXEC SQL OPEN cur1 USING DESCRIPTOR sqlda2;\n\n    while (1)\n    {\n        sqlda_t *cur_sqlda;\n\n        /* Assign descriptor to the cursor  */\n        EXEC SQL FETCH NEXT FROM cur1 INTO DESCRIPTOR sqlda1;\n\n        for (cur_sqlda = sqlda1 ;\n             cur_sqlda != NULL ;\n             cur_sqlda = cur_sqlda->desc_next)\n        {\n            int i;\n            char name_buf[1024];\n            char var_buf[1024];\n\n            /* Print every column in a row. */\n            for (i=0 ; i<cur_sqlda->sqld ; i++)\n            {\n                sqlvar_t v = cur_sqlda->sqlvar[i];\n                char *sqldata = v.sqldata;\n                short sqllen  = v.sqllen;\n\n                strncpy(name_buf, v.sqlname.data, v.sqlname.length);\n                name_buf[v.sqlname.length] = '\\0';\n\n                switch (v.sqltype)\n                {\n                    case ECPGt_char:\n                        memset(&var_buf, 0, sizeof(var_buf));\n                        memcpy(&var_buf, sqldata, (sizeof(var_buf)<=sqllen ? sizeof(var_buf)-1 : sqllen) );\n                        break;\n\n                    case ECPGt_int: /* integer */	e3fd9564992d0f811d35ee61e23d86732218c2b524faada0cbb668fff58ead29	\N	7	10	bge-base-en-v1.5	[0.6294175,0.9500695,-2.738691,-2.0420556,0.6619785,-0.70541525,0.44753754,0.22641306,-1.1913836,-1.0417039,-0.78150773,0.54414505,1.2576473,-0.17692856,0.051363744,0.14244054,-0.7425135,-0.29250962,-0.58658725,0.6208467,-0.6179925,-0.44082233,-0.38915077,-0.2911353,1.5367011,1.7752678,-0.49728113,0.5824009,-0.5916704,1.1520816,0.23810448,0.34888467,0.5582713,-0.41570374,-0.92382175,-0.95063746,0.0151341595,0.47704822,-0.26087943,-0.20241751,0.7842304,0.27123258,0.58872205,-0.7311673,-0.6349487,0.31456095,1.2684476,0.32696092,1.5310298,-1.195572,0.043252476,-0.58906955,-0.056371685,-1.1421279,1.1318178,0.426513,-0.011889793,0.25266397,0.26585978,-0.13506618,1.0418758,0.04074161,-1.0072436,0.9745293,0.65445864,-0.49809492,0.077642076,0.7631319,-0.28196555,-0.9088418,0.2974543,0.1019147,-0.5615331,0.32935625,-0.81455785,-0.286044,-0.18502827,-0.7060593,0.009955629,0.8276792,-0.065456,-0.17996189,0.73051983,-0.86794263,0.23807712,-0.090099595,-0.74372673,0.31707227,0.16227846,0.1087583,0.053392842,0.43526575,-0.45570818,0.9962639,-1.0947226,-0.13715