408	05f89c82-1c05-4b25-b702-da32cbcf4d53	\N	407	409	libpq-events.html	html	\N	\N	32.14. Event System#	\N	\N	\N	\N	32.14. Event System#	\N	\N	\N	\N	18	en	{"title": "32.14. Event System#", "filename": "libpq-events.html", "chunk_count": 6, "chunk_index": 4}	Page: 32.14. Event System#\nSource: libpq-events.html\n\n. (Doing so is recommendable because it eliminates the need to free such storage explicitly when the result is destroyed.)\nPQresultInstanceData\n#\nReturns the result's\ninstanceData\nassociated with\nproc\n, or\nNULL\nif there is none.\nvoid *PQresultInstanceData(const PGresult *res, PGEventProc proc);\n32.14.4. Event Example\n#\nHere is a skeleton example of managing private data associated with libpq connections and results.\n/* required header for libpq events (note: includes libpq-fe.h) */\n#include <libpq-events.h>\n\n/* The instanceData */\ntypedef struct\n{\n    int n;\n    char *str;\n} mydata;\n\n/* PGEventProc */\nstatic int myEventProc(PGEventId evtId, void *evtInfo, void *passThrough);\n\nint\nmain(void)\n{\n    mydata *data;\n    PGresult *res;\n    PGconn *conn =\n        PQconnectdb("dbname=postgres options=-csearch_path=");\n\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        /* PQerrorMessage's result includes a trailing newline */\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        PQfinish(conn);\n        return 1;\n    }\n\n    /* called once on any connection that should receive events.\n     * Sends a PGEVT_REGISTER to myEventProc.\n     */\n    if (!PQregisterEventProc(conn, myEventProc, "mydata_proc", NULL))\n    {\n        fprintf(stderr, "Cannot register PGEventProc\\n");\n        PQfinish(conn);\n        return 1;\n    }\n\n    /* conn instanceData is available */\n    data = PQinstanceData(conn, myEventProc);\n\n    /* Sends a PGEVT_RESULTCREATE to myEventProc */\n    res = PQexec(conn, "SELECT 1 + 1");\n\n    /* result instanceData is available */\n    data = PQresultInstanceData(res, myEventProc);\n\n    /* If PG_COPYRES_EVENTS is used, sends a PGEVT_RESULTCOPY to myEventProc */\n    res_copy = PQcopyResult(res, PG_COPYRES_TUPLES | PG_COPYRES_EVENTS);\n\n    /* result instanceData is available if PG_COPYRES_EVENTS was\n     * used during the PQcopyResult call.\n     */\n    data = PQresultInstanceData(res_copy, myEventProc);\n\n    /* Both clears send a PGEVT_RESULTDESTROY to myEventProc */\n    PQclear(res);\n    PQclear(res_copy);\n\n    /* Sends a PGEVT_CONNDESTROY to myEventProc */\n    PQfinish(conn);\n\n    return 0;\n}\n\nstatic int\nmyEventProc(PGEventId evtId, void *evtInfo, void *passThrough)\n{\n    switch (evtId)\n    {\n        case PGEVT_REGISTER:\n        {\n            PGEventRegister *e = (PGEventRegister *)evtInfo;\n            mydata *data = get_mydata(e->conn);	faf36debdeca9356c5da11e5b46a584c71ccac3806f08094d5b0f27f62c6277d	\N	4	6	bge-base-en-v1.5	[1.4040625,0.7071987,-2.3996325,-1.8423694,1.4883512,-1.3605701,-0.101795845,0.11367243,-0.38446808,-1.9636531,-0.724332,0.2941285,0.84045196,-0.015626643,0.10640634,-0.6072607,-0.039315376,-0.95165247,-0.9937014,0.0893062,0.121062815,-0.25790894,-0.22752842,0.4138228,1.1956238,1.2172668,0.03516237,0.16208175,-1.4351312,0.03954871,-0.21341932,0.012516213,0.16965532,-1.0207795,-0.56291956,-0.8525339,0.49487457,-0.35678053,0.26681226,0.2358708,0.82419753,0.87307894,0.75663304,-1.2304769,0.6291128,-0.6484241,1.2438059,0.25274876,1.1353823,-1.46068,0.52261144,-0.21336989,0.24936007,-0.63743305,2.2226584,0.8691986,-0.118447594,0.46513608,0.09725876,0.083693445,1.3215014,0.56380373,-0.72624433,0.82681483,0.62302613,-0.79359674,-0.69057184,0.39686278,-0.59344506,0.8081272,0.6341299,0.95874745,-0.2941261,0.11942958,-0.007853564,0.0056126667,-0.30441162,-0.54408675,-0.097068116,0.5836873,-0.48781857,-0.37638894,1.0276574,-0.5348675,0.8157982,-0.17569123,-0.7159658,-0.07523397,-0.6513111,0.7060302,0.73105437,-0.6562544,0.63046455,0.19711818,-1.0643063,0.54653466,0.9792313,-0.5356821,-0.15735956,-0.27134678,0.23747243