409	cb3471dd-6e0e-44c3-8dff-3e633056aeec	\N	408	410	libpq-events.html	html	\N	\N	32.14. Event System#	\N	\N	\N	\N	32.14. Event System#	\N	\N	\N	\N	18	en	{"title": "32.14. Event System#", "filename": "libpq-events.html", "chunk_count": 6, "chunk_index": 5}	Page: 32.14. Event System#\nSource: libpq-events.html\n\n/* associate app specific data with connection */\n            PQsetInstanceData(e->conn, myEventProc, data);\n            break;\n        }\n\n        case PGEVT_CONNRESET:\n        {\n            PGEventConnReset *e = (PGEventConnReset *)evtInfo;\n            mydata *data = PQinstanceData(e->conn, myEventProc);\n\n            if (data)\n              memset(data, 0, sizeof(mydata));\n            break;\n        }\n\n        case PGEVT_CONNDESTROY:\n        {\n            PGEventConnDestroy *e = (PGEventConnDestroy *)evtInfo;\n            mydata *data = PQinstanceData(e->conn, myEventProc);\n\n            /* free instance data because the conn is being destroyed */\n            if (data)\n              free_mydata(data);\n            break;\n        }\n\n        case PGEVT_RESULTCREATE:\n        {\n            PGEventResultCreate *e = (PGEventResultCreate *)evtInfo;\n            mydata *conn_data = PQinstanceData(e->conn, myEventProc);\n            mydata *res_data = dup_mydata(conn_data);\n\n            /* associate app specific data with result (copy it from conn) */\n            PQresultSetInstanceData(e->result, myEventProc, res_data);\n            break;\n        }\n\n        case PGEVT_RESULTCOPY:\n        {\n            PGEventResultCopy *e = (PGEventResultCopy *)evtInfo;\n            mydata *src_data = PQresultInstanceData(e->src, myEventProc);\n            mydata *dest_data = dup_mydata(src_data);\n\n            /* associate app specific data with result (copy it from a result) */\n            PQresultSetInstanceData(e->dest, myEventProc, dest_data);\n            break;\n        }\n\n        case PGEVT_RESULTDESTROY:\n        {\n            PGEventR