410	132ffefa-7709-4a9c-ac0e-b5b106f7fba9	\N	409	411	libpq-example.html	html	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	18	en	{"title": "32.23. Example Programs#", "filename": "libpq-example.html", "chunk_count": 6, "chunk_index": 0}	Page: 32.23. Example Programs#\nSource: libpq-example.html\n\n32.23. Example Programs\n#\nThese examples and others can be found in the directory\nsrc/test/examples\nin the source code distribution.\nExample 32.1.\nlibpq\nExample Program 1\n/*\n * src/test/examples/testlibpq.c\n *\n *\n * testlibpq.c\n *\n *      Test the C version of libpq, the PostgreSQL frontend library.\n */\n#include <stdio.h>\n#include <stdlib.h>\n#include "libpq-fe.h"\n\nstatic void\nexit_nicely(PGconn *conn)\n{\n    PQfinish(conn);\n    exit(1);\n}\n\nint\nmain(int argc, char **argv)\n{\n    const char *conninfo;\n    PGconn     *conn;\n    PGresult   *res;\n    int         nFields;\n    int         i,\n                j;\n\n    /*\n     * If the user supplies a parameter on the command line, use it as the\n     * conninfo string; otherwise default to setting dbname=postgres and using\n     * environment variables or defaults for all other connection parameters.\n     */\n    if (argc > 1)\n        conninfo = argv[1];\n    else\n        conninfo = "dbname = postgres";\n\n    /* Make a connection to the database */\n    conn = PQconnectdb(conninfo);\n\n    /* Check to see that the backend connection was successfully made */\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        exit_nicely(conn);\n    }\n\n    /* Set always-secure search path, so malicious users can't take control. */\n    res = PQexec(conn,\n                 "SELECT pg_catalog.set_config('search_path', '', false)");\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SET failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    /*\n     * Should PQclear PGresult whenever it is no longer needed to avoid memory\n     * leaks\n     */\n    PQclear(res);\n\n    /*\n     * Our test case here involves using a cursor, for which we must be inside\n     * a transaction block.  We could do the whole thing with a single\n     * PQexec() of "select * from pg_database", but that's too trivial to make\n     * a good example.\n     */\n\n    /* Start a transaction block */\n    res = PQexec(conn, "BEGIN");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "BEGIN command failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    /*\n     * Fetch rows from pg_database, the system catalog of databases\n     */\n    res = PQexec(conn, "DECLARE myportal CURSOR FOR select * from pg_database");	9e215557c3550c50f0379288e75b00152327dc1c2d6a4e21f20302d7ffa09a53	\N	0	6	bge-base-en-v1.5	[1.5889342,1.0366223,-2.4836767,-1.7838324,0.5527618,-0.92355484,-0.07731327,-0.028249163,-0.6602968,-0.82654685,-0.6857118,0.07901038,0.13111995,0.4458664,0.16180095,-0.49341744,0.3123497,-1.3264266,-0.16255258,-0.68451756,-0.41691265,-0.69105667,-0.12789328,0.12480766,1.1510352,1.0225232,-0.14908735,0.12926057,-0.76257056,-0.2509712,0.13826616,-0.36464486,0.01941218,-1.3676624,-0.6920489,-0.9386554,1.0098205,-0.2628722,0.14309041,0.9054439,1.0878869,0.6570453,0.20392394,-1.0888683,0.89024675,-0.80641025,1.5843257,0.40947753,1.6634653,-1.3160912,-0.09937674,-0.17630148,0.6435221,-0.012287118,1.3291485,1.2716086,0.25350577,0.1876968,-0.033684835,-0.10973892,1.1672835,0.730009,-0.26719815,0.39316553,0.7103722,-0.74866426,-0.5851626,1.2401291,-0.31989014,0.48194808,0.6647342,0.090704836,-0.4183683,-0.36525968,-0.21605161,-0.2860694,-0.12884057,-0.68859345,-0.72450924,1.0028958,0.11001563,0.24701643,-0.1583684,-0.0258187,0.6955914,-0.20573154,-1.0471444,-0.03905505,-0.45537737,0.26928088,1.0308506,-0.20502226,0.29726925,0.32368386,-1.0534798,0.03914