411	b4674d24-1b52-4fe5-a8cd-5758fb4204df	\N	410	412	libpq-example.html	html	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	18	en	{"title": "32.23. Example Programs#", "filename": "libpq-example.html", "chunk_count": 6, "chunk_index": 1}	Page: 32.23. Example Programs#\nSource: libpq-example.html\n\nif (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "DECLARE CURSOR failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    res = PQexec(conn, "FETCH ALL in myportal");\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "FETCH ALL failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    /* first, print out the attribute names */\n    nFields = PQnfields(res);\n    for (i = 0; i < nFields; i++)\n        printf("%-15s", PQfname(res, i));\n    printf("\\n\\n");\n\n    /* next, print out the rows */\n    for (i = 0; i < PQntuples(res); i++)\n    {\n        for (j = 0; j < nFields; j++)\n            printf("%-15s", PQgetvalue(res, i, j));\n        printf("\\n");\n    }\n\n    PQclear(res);\n\n    /* close the portal ... we don't bother to check for errors ... */\n    res = PQexec(conn, "CLOSE myportal");\n    PQclear(res);\n\n    /* end the transaction */\n    res = PQexec(conn, "END");\n    PQclear(res);\n\n    /* close the connection to the database and cleanup */\n    PQfinish(conn);\n\n    return 0;\n}\nExample 32.2.\nlibpq\nExample Program 2\n/*\n * src/test/examples/testlibpq2.c\n *\n *\n * testlibpq2.c\n *      Test of the asynchronous notification interface\n *\n * Start this program, then from psql in another window do\n *   NOTIFY TBL2;\n * Repeat four times to get this program to exit.\n *\n * Or, if you want to get fancy, try this:\n * populate a database with the following commands\n * (provided in src/test/examples/testlibpq2.sql):\n *\n *   CREATE SCHEMA TESTLIBPQ2;\n *   SET search_path = TESTLIBPQ2;\n *   CREATE TABLE TBL1 (i int4);\n *   CREATE TABLE TBL2 (i int4);\n *   CREATE RULE r1 AS ON INSERT TO TBL1 DO\n *     (INSERT INTO TBL2 VALUES (new.i); NOTIFY TBL2);\n *\n * Start this program, then from psql do this four times:\n *\n *   INSERT INTO TESTLIBPQ2.TBL1 VALUES (10);\n */\n\n#ifdef WIN32\n#include <windows.h>\n#endif\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <errno.h>\n#include <sys/select.h>\n#include <sys/time.h>\n#include <sys/types.h>\n\n#include "libpq-fe.h"\n\nstatic void\nexit_nicely(PGconn *conn)\n{\n    PQfinish(conn);\n    exit(1);\n}\n\nint\nmain(int argc, char **argv)\n{\n    const char *conninfo;\n    PGconn     *conn;\n    PGresult   *res;\n    PGnotify   *notify;\n    int         nnotifies;\n\n    /*	38ab09029f70d1e5bd984bf07698dccda8f23fd20667ec6e4c26dd1ec6a8457f	\N	1	6	bge-base-en-v1.5	[1.5433828,0.49350077,-2.089169,-1.4078095,0.76240385,-1.1302079,0.060033206,-0.012664739,-0.2641642,-1.295908,-0.6825771,0.19446704,0.9714553,0.39274895,-0.046168152,-0.16158457,0.076768026,-1.5921419,-0.42945534,-0.06472361,-0.20281555,-0.1285311,-0.41784626,0.16505475,1.0778021,0.4246784,-0.60793525,0.030919792,-0.94293326,0.5284276,-0.06535292,0.63711,-0.19106725,-1.4979074,-0.85628337,-0.37373596,0.6040433,-0.750329,-0.15133603,1.0503606,0.783336,0.14216709,0.39515278,-0.8751198,0.8832523,-1.2038733,1.6372048,0.64902115,1.6496485,-1.1638129,-0.2791246,-0.68044513,0.14421777,-0.35143322,1.2837566,1.7197886,-0.18015954,0.31581217,0.25102475,0.22288181,1.2900498,0.59953594,-0.20815045,1.0722774,1.0639801,-0.46549758,-0.5411892,1.0397663,-0.58002734,0.44688955,0.7571495,0.4656372,-0.4218001,-0.10653905,-0.13542317,0.18900101,-0.4531336,-0.68961626,-0.6672887,1.2537636,-0.43550673,-0.08480469,0.025670735,-0.47640994,0.16134141,-0.07221679,-1.0159637,-0.4819626,-0.5521017,0.2732373,0.68777394,-0.62465125,0.59623915,0.16891058,-0.9992846,0.35077137,0.4473616,-0.37411964,-0.4475185,-0.45980352,0