412	f8931490-c1fd-4f72-9e39-2e7a520fb88c	\N	411	413	libpq-example.html	html	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	18	en	{"title": "32.23. Example Programs#", "filename": "libpq-example.html", "chunk_count": 6, "chunk_index": 2}	Page: 32.23. Example Programs#\nSource: libpq-example.html\n\n* If the user supplies a parameter on the command line, use it as the\n     * conninfo string; otherwise default to setting dbname=postgres and using\n     * environment variables or defaults for all other connection parameters.\n     */\n    if (argc > 1)\n        conninfo = argv[1];\n    else\n        conninfo = "dbname = postgres";\n\n    /* Make a connection to the database */\n    conn = PQconnectdb(conninfo);\n\n    /* Check to see that the backend connection was successfully made */\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        exit_nicely(conn);\n    }\n\n    /* Set always-secure search path, so malicious users can't take control. */\n    res = PQexec(conn,\n                 "SELECT pg_catalog.set_config('search_path', '', false)");\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SET failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    /*\n     * Should PQclear PGresult whenever it is no longer needed to avoid memory\n     * leaks\n     */\n    PQclear(res);\n\n    /*\n     * Issue LISTEN command to enable notifications from the rule's NOTIFY.\n     */\n    res = PQexec(conn, "LISTEN TBL2");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "LISTEN command failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    /* Quit after four notifies are received. */\n    nnotifies = 0;\n    while (nnotifies < 4)\n    {\n        /*\n         * Sleep until something happens on the connection.  We use select(2)\n         * to wait for input, but you could also use poll() or similar\n         * facilities.\n         */\n        int         sock;\n        fd_set      input_mask;\n\n        sock = PQsocket(conn);\n\n        if (sock < 0)\n            break;              /* shouldn't happen */\n\n        FD_ZERO(&input_mask);\n        FD_SET(sock, &input_mask);\n\n        if (select(sock + 1, &input_mask, NULL, NULL, NULL) < 0)\n        {\n            fprintf(stderr, "select() failed: %s\\n", strerror(errno));\n            exit_nicely(conn);\n        }\n\n        /* Now check for input */\n        PQconsumeInput(conn);\n        while ((notify = PQnotifies(conn)) != NULL)\n        {\n            fprintf(stderr,\n                    "ASYNC NOTIFY of '%s' received from backend PID %d\\n",\n                    notify->relname, notify->be_pid);	676f18b6a390056c3ffc477868332b5675a1f353f93d59795b51be3874bd83ff	\N	2	6	bge-base-en-v1.5	[1.3139057,0.7652261,-2.3976717,-1.6615348,1.0945449,-0.7345261,0.17493689,-0.23931967,-0.808615,-0.97926575,-0.8265514,0.33567902,0.32234105,0.3268822,0.44085452,-0.37150547,-0.44150278,-1.0484676,0.002798023,-0.79024905,-0.7084512,-0.7620588,0.011033032,0.1760069,1.300572,1.3321408,-0.4776108,-0.029699825,-0.8520976,-0.16690822,0.03724925,0.6675302,-0.26374626,-0.75380284,-1.3449619,-1.0862226,0.51051784,-0.36812764,-0.38490355,0.8224418,1.1204143,0.38033995,0.3318784,-1.319028,0.31143835,-1.0030243,1.7346025,-0.18561909,1.4378732,-2.0853343,-0.26682705,-0.011485657,0.384868,-0.45077282,1.5204511,1.2566555,-0.11578042,0.6734179,0.078506365,0.18816046,1.8559982,0.35728216,-0.37895936,1.2782629,0.67927206,-0.5666521,-1.1749656,1.343867,-0.031000946,0.72089356,0.062255748,0.10508934,-0.86004174,0.09163906,-0.015029495,-0.031913746,-0.21328384,-0.82757896,-0.30291528,0.8200212,-0.09015484,0.016730161,0.34669027,-0.40018356,0.2382278,-0.23677377,-0.9360904,-0.104748644,-0.5954539,0.27100924,0.53071696,-0.4237878,0.1317603,0.1455711,-0.795791,0.46774563