413	70a114a1-f888-4a9a-81b2-7c2dae24fe0f	\N	412	414	libpq-example.html	html	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	18	en	{"title": "32.23. Example Programs#", "filename": "libpq-example.html", "chunk_count": 6, "chunk_index": 3}	Page: 32.23. Example Programs#\nSource: libpq-example.html\n\nPQfreemem(notify);\n            nnotifies++;\n            PQconsumeInput(conn);\n        }\n    }\n\n    fprintf(stderr, "Done.\\n");\n\n    /* close the connection to the database and cleanup */\n    PQfinish(conn);\n\n    return 0;\n}\nExample 32.3.\nlibpq\nExample Program 3\n/*\n * src/test/examples/testlibpq3.c\n *\n *\n * testlibpq3.c\n *      Test out-of-line parameters and binary I/O.\n *\n * Before running this, populate a database with the following commands\n * (provided in src/test/examples/testlibpq3.sql):\n *\n * CREATE SCHEMA testlibpq3;\n * SET search_path = testlibpq3;\n * SET standard_conforming_strings = ON;\n * CREATE TABLE test1 (i int4, t text, b bytea);\n * INSERT INTO test1 values (1, 'joe''s place', '\\000\\001\\002\\003\\004');\n * INSERT INTO test1 values (2, 'ho there', '\\004\\003\\002\\001\\000');\n *\n * The expected output is:\n *\n * tuple 0: got\n *  i = (4 bytes) 1\n *  t = (11 bytes) 'joe's place'\n *  b = (5 bytes) \\000\\001\\002\\003\\004\n *\n * tuple 0: got\n *  i = (4 bytes) 2\n *  t = (8 bytes) 'ho there'\n *  b = (5 bytes) \\004\\003\\002\\001\\000\n */\n\n#ifdef WIN32\n#include <windows.h>\n#endif\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <stdint.h>\n#include <string.h>\n#include <sys/types.h>\n#include "libpq-fe.h"\n\n/* for ntohl/htonl */\n#include <netinet/in.h>\n#include <arpa/inet.h>\n\n\nstatic void\nexit_nicely(PGconn *conn)\n{\n    PQfinish(conn);\n    exit(1);\n}\n\n/*\n * This function prints a query result that is a binary-format fetch from\n * a table defined as in the comment above.  We split it out because the\n * main() function uses it twice.\n */\nstatic void\nshow_binary_results(PGresult *res)\n{\n    int         i,\n                j;\n    int         i_fnum,\n                t_fnum,\n                b_fnum;\n\n    /* Use PQfnumber to avoid assumptions about field order in result */\n    i_fnum = PQfnumber(res, "i");\n    t_fnum = PQfnumber(res, "t");\n    b_fnum = PQfnumber(res, "b");\n\n    for (i = 0; i < PQntuples(res); i++)\n    {\n        char       *iptr;\n        char       *tptr;\n        char       *bptr;\n        int         blen;\n        int         ival;\n\n        /* Get the field values (we ignore possibility they are null!) */\n        iptr = PQgetvalue(res, i, i_fnum);\n        tptr = PQgetvalue(res, i, t_fnum);\n        bptr = PQgetvalue(res, i, b_fnum);\n\n        /*\n         * The binary representation of INT4 is in network byte order, which\n         * we'd better coerce to the local byte order.\n         */	3cdf64224c4d4a79645c4cf889e9e496715dfac703e19531f849564a06608726	\N	3	6	bge-base-en-v1.5	[1.4135247,0.4390053,-2.116553,-1.6661271,1.0363845,-0.94619656,-0.27783784,-0.21333447,-0.5348488,-1.1481975,-0.9957852,0.3957804,0.3154815,0.20457242,-0.041668355,-0.6916572,-0.30266377,-1.2778856,0.14681645,-0.46434572,-0.087943815,0.4597321,-0.48702213,-0.041918628,0.6988469,0.5703549,-0.34197557,0.421675,-1.2084069,-0.037523784,0.37780204,0.432319,-0.49749416,-1.2015622,-1.0913047,-0.4587453,0.48652303,-0.41715378,0.08546262,0.9402488,0.99245054,0.44092792,-0.06750329,-0.8526003,0.6724815,-0.88954663,1.3786694,0.8634981,1.1772457,-1.5095978,-0.09501511,-0.63976634,0.3079562,-0.111570366,1.6350973,1.443191,-0.52814233,0.05156188,-0.055892278,0.101828076,1.2305185,0.40051347,-0.99867475,1.0650569,0.52673656,-0.29000464,-0.7969318,0.66123813,-0.4502388,0.5464302,0.6587982,0.27269882,-0.19283962,-0.2681718,-0.82220304,-0.36888114,-0.8970105,-0.46154326,-0.1820067,1.2823151,-0.213356,0.2194113,-0.1219842,0.3936817,0.12779166,-0.002395053,-0.44233012,-0.45920905,-0.26358905,0.9832523,0.80841035,-0.12160494,0.1810624