414	709d1f7f-c3e9-4081-afb3-f57d56f9c0e3	\N	413	415	libpq-example.html	html	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	18	en	{"title": "32.23. Example Programs#", "filename": "libpq-example.html", "chunk_count": 6, "chunk_index": 4}	Page: 32.23. Example Programs#\nSource: libpq-example.html\n\nival = ntohl(*((uint32_t *) iptr));\n\n        /*\n         * The binary representation of TEXT is, well, text, and since libpq\n         * was nice enough to append a zero byte to it, it'll work just fine\n         * as a C string.\n         *\n         * The binary representation of BYTEA is a bunch of bytes, which could\n         * include embedded nulls so we have to pay attention to field length.\n         */\n        blen = PQgetlength(res, i, b_fnum);\n\n        printf("tuple %d: got\\n", i);\n        printf(" i = (%d bytes) %d\\n",\n               PQgetlength(res, i, i_fnum), ival);\n        printf(" t = (%d bytes) '%s'\\n",\n               PQgetlength(res, i, t_fnum), tptr);\n        printf(" b = (%d bytes) ", blen);\n        for (j = 0; j < blen; j++)\n            printf("\\\\%03o", bptr[j]);\n        printf("\\n\\n");\n    }\n}\n\nint\nmain(int argc, char **argv)\n{\n    const char *conninfo;\n    PGconn     *conn;\n    PGresult   *res;\n    const char *paramValues[1];\n    int         paramLengths[1];\n    int         paramFormats[1];\n    uint32_t    binaryIntVal;\n\n    /*\n     * If the user supplies a parameter on the command line, use it as the\n     * conninfo string; otherwise default to setting dbname=postgres and using\n     * environment variables or defaults for all other connection parameters.\n     */\n    if (argc > 1)\n        conninfo = argv[1];\n    else\n        conninfo = "dbname = postgres";\n\n    /* Make a connection to the database */\n    conn = PQconnectdb(conninfo);\n\n    /* Check to see that the backend connection was successfully made */\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        exit_nicely(conn);\n    }\n\n    /* Set always-secure search path, so malicious users can't take control. */\n    res = PQexec(conn, "SET search_path = testlibpq3");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "SET failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    /*\n     * The point of this program is to illustrate use of PQexecParams() with\n     * out-of-line parameters, as well as binary transmission of data.\n     *\n     * This first example transmits the parameters as text, but receives the\n     * results in binary format.  By using out-of-line parameters we can avoid\n     * a lot of tedious mucking about with quoting and escaping, even though	a2146a61a215b940d45afe465759356f23966cf996a9f932a54965bdd21782d8	\N	4	6	bge-base-en-v1.5	[1.3047472,0.8248789,-1.8191495,-1.8433212,0.981381,-0.792261,-0.62658715,-0.041264948,-0.906449,-1.506237,-0.6115762,0.37777358,0.93342036,0.16329946,0.21069378,-0.85509557,-0.07985011,-1.0896244,0.582971,-0.39990664,-0.3109005,0.36285493,-0.112623036,-0.5014735,0.9339592,0.7981057,-0.10850401,0.45974958,-1.2457249,0.21687491,0.7538125,-0.09260551,0.10944604,-0.6653656,-1.2123269,-0.1482746,0.24537295,0.18525885,-0.032279186,0.6982008,0.924778,0.45571792,-0.09406388,-0.33409128,0.3141498,-0.49865806,1.1197674,0.6297521,1.0484289,-1.6612487,-0.0029728855,-0.2006175,0.089083746,-0.52637136,1.825965,0.85111344,-0.75429034,-0.035685968,-0.23094164,0.6343734,1.398207,1.0604131,-1.2216333,1.5260744,0.74747217,-0.24155062,-1.0325123,0.14480004,-0.20836073,0.062166065,0.3724414,-0.0010020157,-0.7728315,0.12747788,-0.60018474,-0.674046,-0.45834646,-0.5345891,-0.038776044,1.3297926,-0.27551332,-0.20496365,-0.01542826,0.40724644,0.29547536,0.05301897,-0.6760906,-0.14212132,-0.33185583,0.81745803,0.35789588,-0.5608152,0.10543125,0.18521811,-0.78765965,0.2265484,0.115192495,-0.025907405,