415	2a2185d0-4fa2-4297-96ec-329856d5cc8e	\N	414	416	libpq-example.html	html	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	32.23. Example Programs#	\N	\N	\N	\N	18	en	{"title": "32.23. Example Programs#", "filename": "libpq-example.html", "chunk_count": 6, "chunk_index": 5}	Page: 32.23. Example Programs#\nSource: libpq-example.html\n\n* the data is text.  Notice how we don't have to do anything special with\n     * the quote mark in the parameter value.\n     */\n\n    /* Here is our out-of-line parameter value */\n    paramValues[0] = "joe's place";\n\n    res = PQexecParams(conn,\n                       "SELECT * FROM test1 WHERE t = $1",\n                       1,       /* one param */\n                       NULL,    /* let the backend deduce param type */\n                       paramValues,\n                       NULL,    /* don't need param lengths since text */\n                       NULL,    /* default to all text params */\n                       1);      /* ask for binary results */\n\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SELECT failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    show_binary_results(res);\n\n    PQclear(res);\n\n    /*\n     * In this second example we transmit an integer parameter in binary form,\n     * and again retrieve the results in binary form.\n     *\n     * Although we tell PQexecParams we are letting the backend deduce\n     * parameter type, we really force the decision by casting the parameter\n     * symbol in the query text.  This is a good safety measure when sending\n     * binary parameters.\n     */\n\n    /* Convert integer value "2" to network byte order */\n    binaryIntVal = htonl((uint32_t) 2);\n\n    /* Set up parameter arrays for PQexecParams */\n    paramValues[0] = (char *) &binaryIntVal;\n    paramLengths[0] = sizeof(binaryIntVal);\n    paramFormats[0] = 1;        /* binary */\n\n    res = PQexecParams(conn,\n                       "SELECT * FROM test1 WHERE i = $1::int4",\n                       1,       /* one param */\n                       NULL,    /* let the backend deduce param type */\n                       paramValues,\n                       paramLengths,\n                       paramFormats,\n                       1);      /* ask for binary results */\n\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SELECT failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    show_binary_results(res);\n\n    PQclear(res);\n\n    /* close the connection to the database and cleanup */\n    PQfinish(conn);\n\n    return 0;\n}	d4bdbe55f3b367b6613c61788951f1e5933723795858a829fb4ed8393a9a2516	\N	5	6	bge-base-en-v1.5	[1.2623105,0.9165952,-2.1695373,-1.536235,1.6693515,-0.508167,-0.35737094,0.23962545,-0.55093694,-0.97308993,-0.52055025,0.7123357,0.42077345,0.06657884,-0.1543315,-1.168637,-0.35604355,-1.6998739,0.07870792,-0.08792115,-0.44679248,0.20564415,-0.42894363,-0.67453206,1.0042046,0.57168126,-0.5119281,0.4612371,-1.3775375,0.10318673,0.034724463,0.02079654,0.050416127,-0.7070117,-0.92984504,-0.44705194,0.6070992,0.07293157,-0.21421923,1.0990224,1.458116,0.09293658,0.4519481,-0.30283034,0.47152352,-1.08013,1.299479,0.6432471,1.3374945,-1.5125592,0.050226476,-0.8025325,0.3156987,-1.0906334,1.9312088,0.99072725,-0.80372196,0.49886,0.5469412,0.2838994,1.0813055,0.6803147,-1.3509245,1.2766174,0.5564953,-0.1895822,-0.9758385,0.21489334,-0.6700463,0.27259254,0.42333037,0.33297035,-0.89638287,0.09924029,-0.7909715,-0.25816834,-0.9509283,-0.5795116,-0.2796071,1.2033658,-0.24504906,-0.13069879,0.04551326,0.291706,0.19836935,0.46638492,-0.70433336,-0.07800421,-0.44004735,0.81108147,0.038652346,-0.62906164,0.09676321,0.11270388,-0.7729877,0.32028395,-0.033457242,-0.98677087,0.41751102,-0.2727389,-0.018536767,0.3205006,-0.8450623,0.36651957,0.19903813,0.60230374,0.97286785,0.4124689,-0.481654,-1.0802394,0.21860802,0.9