--
-- Name: hybrid_search(text, public.vector, integer); Type: FUNCTION; Schema: rag; Owner: postgres
--

CREATE FUNCTION rag.hybrid_search(query_text text, query_embedding public.vector, match_count integer DEFAULT 10) RETURNS TABLE(id bigint, title text, heading text, content text, url text, final_score double precision)
    LANGUAGE sql
    AS $$

WITH

-- ---------------------------------------------------------------------------
-- RECHERCHE SÉMANTIQUE (Vecteurs)
-- ---------------------------------------------------------------------------
semantic_search AS (
    SELECT
        d.id, d.title, d.heading, d.content, d.url,
        1.0 / (60 + ROW_NUMBER() OVER (ORDER BY d.embedding <=> query_embedding)) AS score
    FROM rag.documents d
    WHERE d.embedding IS NOT NULL
    ORDER BY d.embedding <=> query_embedding
    LIMIT 100
),

-- ---------------------------------------------------------------------------
-- RECHERCHE TEXTUELLE (FTS) - Trié rigoureusement avant d'isoler le Top 100
-- ---------------------------------------------------------------------------
fts_search AS (
    SELECT
        d.id, d.title, d.heading, d.content, d.url,
        1.0 / (
            60 + ROW_NUMBER() OVER (
                ORDER BY ts_rank_cd(d.fts_tokens, websearch_to_tsquery('simple', query_text)) DESC
            )
        ) AS score
    FROM rag.documents d
    WHERE d.fts_tokens @@ websearch_to_tsquery('simple', query_text)
    ORDER BY ts_rank_cd(d.fts_tokens, websearch_to_tsquery('simple', query_text)) DESC
    LIMIT 100
),

-- ---------------------------------------------------------------------------
-- FUSION DES RANGS (RRF via UNION ALL)
-- ---------------------------------------------------------------------------
rrf AS (
    SELECT id, title, heading, content, url, score FROM semantic_search
    UNION ALL
    SELECT id, title, heading, content, url, score FROM fts_search
)

SELECT
    id,
    MAX(title) AS title,
    MAX(heading) AS heading,
    MAX(content) AS content,
    MAX(url) AS url,
    SUM(score)::FLOAT AS final_score
FROM rrf
GROUP BY id
ORDER BY final_score DESC
LIMIT match_count;

$$;


ALTER FUNCTION rag.hybrid_search(query_text text, query_embedding public.vector, match_count integer) OWNER TO postgres;

